"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["17452"],{60877(e){e.exports=JSON.parse('{"id":"FIN-1131","slug":"net-revenue-retention","term":"Net Revenue Retention (NRR)","also_known_as":["NRR"],"difficulty":"Advanced","definition":"Net revenue retention (NRR) is the percentage of recurring revenue a company keeps from an existing group of customers over a period, including upgrades and expansion, minus downgrades and cancellations.","explanation":["NRR shows whether existing customers are spending more or less over time. It is a key measure for subscription businesses, particularly software companies that sell to other businesses.","It is usually calculated by starting with recurring revenue from a set of customers at the beginning of the period, adding expansion revenue from those customers, subtracting contraction and churn, and dividing by the starting revenue. New customers are excluded.","For example, a company starts the year with 10,000,000 of annual recurring revenue. During the year, existing customers add 2,000,000 through upgrades, while downgrades reduce revenue by 500,000 and cancellations by 700,000. NRR is 10.8 million divided by 10 million, or 108%.","An NRR above 100% means the company grows even without new customers, which investors value highly. NRR is also called net dollar retention. It differs from gross revenue retention, which ignores expansion and shows only how much revenue is lost."],"note":"","total":1500,"prev":{"slug":"net-realizable-value","term":"Net Realizable Value"},"next":{"slug":"net-stable-funding-ratio","term":"Net Stable Funding Ratio (NSFR)"}}')}}]);